import{z as o,x as s,o as e,c as d,q as i,j as B,D as E,d as A,s as t,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"融资约束的度量","description":"","frontmatter":{"title":"融资约束的度量","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-financing-constraints.md","filePath":"econ/cf-financing-constraints.md","lastUpdated":1791063341000}'),p={name:"econ/cf-financing-constraints.md"};function c(F,a,m,h,C,f){const r=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="融资约束的度量" tabindex="-1">融资约束的度量 <a class="header-anchor" href="#融资约束的度量" aria-label="Permalink to &quot;融资约束的度量&quot;">​</a></h1><div class="epigraph"><p>融资约束不是一个可以直读的变量：你观测到的每一条代理——现金流、杠杆、规模、年龄——同时被需求与供给两只手推动；度量的一半工作是先把它们分开。</p><footer>—— 据 Fazzari–Hubbard–Petersen 1988 与 Kaplan–Zingales 1997 的分歧整理</footer></div><p><a href="/econ/mt-map">上一课</a>把货币理论收在三张清单上：承诺、预期与实施必须同时成立，名义锚才钉得住。那是资金的<strong>价格</strong>如何被管理；本课程转向资金的需求方——企业。主干课的<a href="/econ/pecking-order">优序融资</a>钉过定性结论：外部融资带逆向选择溢价，所以企业先用内部资金、再举债、最后发股（Myers–Majluf 1984 的逻辑）。缺口在定量一侧：溢价多深、约束多紧，得先能度量，后面的分配、发行、并购才谈得上「钱从哪来、往哪去」。本课程之后依次过股利与回购、IPO 与发行时机、并购浪潮、治理实证、ESG 与破产重整。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/modigliani-miller">莫迪利亚尼–米勒</a>把无关性讲清：完美市场里投资只看项目的 NPV，钱从内部还是外部来没有区别。融资约束是无关性失效后的残差：内外资金不等价，好项目可能因为拿不到钱而放弃。麻烦在「约束」不可直接观测——投资、现金流与资产负债表同时被需求侧与供给侧推动。现金流高，可能是机会多所以投资与现金流一起涨，也可能是钱容易拿。度量的第一件事就是把手分开。</p><p><span class="marginnote">融资约束可以翻译成「想借借不到、想发发不出」的差价：外部人怕被坑，要收一笔逆向选择溢价，约束紧不紧就是这笔溢价有多贵——贵到好项目算不过账来，企业只好放弃项目或囤现金。它是 MM 无关性被现实打破后留下的那道缝。</span></p><h3 id="三族度量" tabindex="-1">三族度量 <a class="header-anchor" href="#三族度量" aria-label="Permalink to &quot;三族度量&quot;">​</a></h3><p>分组法：先按事前特征分组（规模、年龄、是否派息），再比较组内投资对现金流的敏感度。Fazzari–Hubbard–Petersen 1988 用低派息组的高敏感度支持约束存在；Kaplan–Zingales 1997 对同一样本反查，发现敏感度最高的公司恰恰现金充裕——敏感度本身不是约束的充分统计。指数法：把财务变量压成一个标量，KZ 指数用杠杆、派息、现金、托宾 \\(Q\\) 线性组合；SA 指数只留外生性强的两个变量 \\(\\mathrm{SA}=-0.737\\,\\mathrm{Size}+0.043\\,\\mathrm{Size}^{2}-0.040\\,\\mathrm{Age}\\)（Hadlock–Pierce 2010），代价是丢掉信息含量。结构法：从投资的欧拉方程或动态模型反解摩擦参数，能做反事实，但要付分布假设的代价。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正确姿势是把指数当<strong>筛选器</strong>而不是结论：SA 高的公司先被标记为「可能受约束」，再用设计去识别。识别语言来自<a href="/econ/corporate-finance-identification">公司金融的实证识别</a>：现金流是需求代理，不能直接当约束读；要找只推供给侧的冲击。Rauh 2006 的设计是范例：养老金供款义务是法定支出，外生地抽走内部资金，其后的投资响应才读得出约束的松紧。敏感度还会随金融市场发展而衰减，横截面比较要控制制度环境。</p><p><span class="marginnote">直觉类比：SA 指数像体检的初筛指标——血压偏高只是把你标成「值得复查」，不等于确诊；确诊要靠后续有针对性的检查（识别设计）。把初筛读数直接当结论，等于把「该复查」当成「有病」。</span></p>',11)),(e(),B(l,null,{default:E(()=>[t(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM%5B%22MM%20%E6%97%A0%E5%85%B3%E6%80%A7%EF%BC%9A%E6%8A%95%E8%B5%84%E5%8F%AA%E7%9C%8B%20NPV%22%5D%20--%3E%20FRIC%5B%22%E6%91%A9%E6%93%A6%EF%BC%9A%E5%A4%96%E9%83%A8%E6%BA%A2%E4%BB%B7%E4%B8%8E%E6%8A%B5%E6%8A%BC%E5%93%81%22%5D%0A%20%20FRIC%20--%3E%20MEAS%5B%22%E5%BA%A6%E9%87%8F%EF%BC%9A%E5%88%86%E7%BB%84%20%2F%20%E6%8C%87%E6%95%B0%20%2F%20%E7%BB%93%E6%9E%84%22%5D%0A%20%20MEAS%20--%3E%20SCREEN%5B%22%E7%AD%9B%E9%80%89%E5%8F%AF%E8%83%BD%E5%8F%97%E7%BA%A6%E6%9D%9F%E7%9A%84%E4%BC%81%E4%B8%9A%22%5D%0A%20%20SCREEN%20--%3E%20IDENT%5B%22%E8%AF%86%E5%88%AB%EF%BC%9A%E5%8F%AA%E6%8E%A8%E4%BE%9B%E7%BB%99%E4%BE%A7%E7%9A%84%E5%86%B2%E5%87%BB%22%5D%0A%20%20IDENT%20--%3E%20READ%5B%22%E8%AF%BB%E6%95%B0%EF%BC%9A%E7%BA%A6%E6%9D%9F%E7%9A%84%E4%BB%A3%E7%90%86%EF%BC%8C%E9%9D%9E%E7%BA%A6%E6%9D%9F%E6%9C%AC%E8%BA%AB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[A("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"为什么 SA 指数坚持只用规模与年龄：指数的每个输入都是一个会内生波动的财务变量。杠杆在约束紧时本来就高，把它放进指数等于把结果放进定义；SA 的取舍是牺牲信息换输入的外生性。为什么分组法会错：组内敏感度混合了投资机会分布与融资成本分布，两组机会分布不同时，敏感度差读不出约束差。为什么约束对投资是非线性的：约束不紧时企业边际上用内部资金定价，约束紧到抵押品边界才跳变——线性回归平均掉的恰是最要紧的那一段。",-1)),(e(),B(l,null,{default:E(()=>[t(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E8%A7%82%E6%B5%8B%EF%BC%9A%E6%8A%95%E8%B5%84%E5%AF%B9%E7%8E%B0%E9%87%91%E6%B5%81%E9%AB%98%E6%95%8F%E6%84%9F%22%5D%20--%3E%20H1%5B%22%E8%A7%A3%E9%87%8A%E4%B8%80%EF%BC%9A%E8%9E%8D%E8%B5%84%E7%BA%A6%E6%9D%9F%E7%B4%A7%22%5D%0A%20%20O%20--%3E%20H2%5B%22%E8%A7%A3%E9%87%8A%E4%BA%8C%EF%BC%9A%E6%8A%95%E8%B5%84%E6%9C%BA%E4%BC%9A%E5%A4%9A%22%5D%0A%20%20KZ%5B%22Kaplan%E2%80%93Zingales%20%E5%8F%8D%E6%9F%A5%E5%90%8C%E4%B8%80%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20F%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E6%9C%80%E9%AB%98%E7%9A%84%E5%85%AC%E5%8F%B8%E7%8E%B0%E9%87%91%E5%85%85%E8%A3%95%22%5D%0A%20%20F%20--%3E%20C%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E4%B8%8D%E6%98%AF%E7%BA%A6%E6%9D%9F%E7%9A%84%E5%85%85%E5%88%86%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20W%5B%22%E5%87%BA%E8%B7%AF%EF%BC%9A%E5%8F%AA%E6%8E%A8%E4%BE%9B%E7%BB%99%E4%BE%A7%E7%9A%84%E5%86%B2%E5%87%BB%22%5D%20--%3E%20R%5B%22%E5%A6%82%20Rauh%20%E7%9A%84%E5%85%BB%E8%80%81%E9%87%91%E4%BE%9B%E6%AC%BE%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20R%20--%3E%20C%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">数字实例：规模相同、年龄 20 年与 60 年的两家公司，SA 指数相差 \\(-0.040 \\times 40 = -1.6\\)——越老指数越低，读作约束越松；反过来，小而年轻的公司落在指数最高处，与「初创企业最难借钱」的直觉一致。指数用年月与体量这些几乎不被企业操纵的变量，换来的就是这份外生性。</span></p><p><span class="marginnote">SA 指数的系数来自 Hadlock–Pierce 2010 的美国上市公司样本：规模每大一个对数单位约 \\(-0.737\\)，年龄每老一年约 \\(-0.040\\)，二次项 \\(0.043\\) 防止指数在超大企业处掉头。把系数搬到非上市或新兴市场样本之前，必须重估。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>度量的是「约束的代理」，不是约束本身；SA 与 KZ 的排序相关性并不高，选哪个先想清楚愿意犯哪种错。指数有地域与时代的外推边界：系数是美国上市样本的产物，非上市企业与银行主导金融体系下的约束结构不同。结构法给反事实，但参数依赖分布假设，假设错了反事实就是修辞。本课不展开银行信贷供给如何放大约束，那是后续银行课程的领域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>融资约束是 MM 无关性失效后的残差，混合了信息摩擦、代理问题与抵押品限制。</li><li>投资-现金流敏感度不是约束的充分统计：Kaplan–Zingales 对 Fazzari–Hubbard–Petersen 的反驳钉死这一条。</li><li>指数是筛选器不是结论；SA 指数用外生性换信息含量，系数出域要重估。</li><li>识别要找只推供给侧的冲击；现金流是需求代理，不能直接当约束读。</li><li>出处：Modigliani–Miller 1958；Myers–Majluf 1984；Fazzari–Hubbard–Petersen 1988；Kaplan–Zingales 1997；Hadlock–Pierce 2010。</li></ul>',6))])}const g=o(p,[["render",c]]);export{u as __pageData,g as default};
